 const sheet=el('div','traveller-sheet'),head=el('header','traveller-header'),brand=el('div'),title=el('h2','', 'Choose whose story you carry');title.id='traveller-title';brand.append(el('small','','ASH & AETHER · CLAY AND WATER'),title,el('p','','One beginning becomes the shared journey. Every road and commission stays in that character’s save.'));head.append(brand);const close=el('button','traveller-close','Return');head.append(close);sheet.append(head);
 const layout=el('div','traveller-layout'),roster=el('nav','traveller-roster');roster.setAttribute('aria-label','Seven playable travellers');const stage=el('section','traveller-stage'),canvas=el('canvas','traveller-model');canvas.setAttribute('aria-label','Rotating character sculpture; drag to turn');const ring=el('div','traveller-plinth');stage.append(ring,canvas);const turnbar=el('div','traveller-turnbar'),left=el('button','','↶'),right=el('button','','↷');left.setAttribute('aria-label','Turn character left');right.setAttribute('aria-label','Turn character right');turnbar.append(left,el('span','','Drag to turn · front & back'),right);stage.append(turnbar);const visualNote=el('small','traveller-art-note','Dimensional study from the original character art');stage.append(visualNote);const details=el('section','traveller-details');layout.append(roster,stage,details);sheet.append(layout);
 const foot=el('div','traveller-footer');foot.append(el('p','','Your lead stays your lead when the roads meet. Companions join the same crew; the region’s commissions open along that journey.'),el('small','','Journey slots and companion drop-in are local to this browser. Starting again preserves the earlier journey.'));sheet.append(foot);veil.append(sheet);document.body.append(veil);
 const drafts=new Map(CREW.map((_,hero)=>[hero,normalizeJourney(hero,profiles[hero]?.value?.world?.journey||(state?.journey?.hero===hero?state.journey:journeyWeave(hero,hero)))]));
