 left.onclick=()=>model.turn(-.45);right.onclick=()=>model.turn(.45);
 const cards=[];for(const o of ORIGINS){const b=el('button','traveller-card');b.dataset.hero=o.hero;b.type='button';const portrait=el('span','traveller-mini');portrait.style.backgroundPosition='0% '+(o.hero/6*100)+'%';const copy=el('span'),summary=profileSummary(profiles[o.hero]);copy.append(el('strong','',CREW[o.hero].name),el('small','',summary?summary.label:bios[o.hero][0]));b.append(portrait,copy);b.onclick=()=>{selected=o;weave=drafts.get(o.hero);render();};const row=el('div','traveller-row');row.append(b);if(summary){const quick=el('button','traveller-quick',summary.ready&&canJoin&&!(state?.party||[]).includes(o.hero)?'+':'▷');const joins=summary.ready&&canJoin&&!(state?.party||[]).includes(o.hero);quick.setAttribute('aria-label',joins?'Invite '+CREW[o.hero].name+' to active crew':'Resume '+CREW[o.hero].name+' journey');quick.title=joins?'Join active crew':'Resume journey';quick.onclick=()=>action(()=>joins?onJoin?.(o.hero):onResume?.(o.hero));row.append(quick);}roster.append(row);cards.push(b);}
 function dismiss(){if(closed)return;closed=true;activeRoster=null;model.destroy();veil.remove();document.removeEventListener('keydown',keys,true);document.removeEventListener('traveller-input',controllerInput);previous?.focus();onClose?.();}close.onclick=dismiss;
