 const lead=state?.journey?.hero??state?.chronicle?.hero??state?.party?.[0]??0,bodyState=id===lead?state:profile?.value?.world||state,body=legacySummary(bodyState,id);model.setLegacy(body.visual);
 const bodyPanel=el('section','traveller-body-history');bodyPanel.setAttribute('aria-label',CREW[id].name+' body history');bodyPanel.append(el('small','','THE BODY REMEMBERS'),el('h4','',body.traitName),el('p','',body.description));if(body.deed)bodyPanel.append(el('p','traveller-deed','LAST DEED · '+body.deed));if(body.signature)bodyPanel.append(el('p','traveller-signature','SIGNATURE · '+body.signature));if(body.tradeoff)bodyPanel.append(el('p','traveller-tradeoff',body.tradeoff));
 if(body.unlocked.length){const forms=el('div','traveller-forms');for(const form of HERO_TRANSFORMATIONS.filter(t=>body.unlocked.includes(t.id))){const current=form.id===body.equipped,b=el('button',current?'attuned':'',(current?'✓ ':'')+form.name+(current?' · attuned':body.firstAttunement?' · first attunement free':' · 1 Ether'));b.type='button';b.disabled=current||bodyState.mode!=='field'||(!body.firstAttunement&&!(bodyState.items?.ether>=1));b.title=form.description+' '+form.tradeoff;b.onclick=()=>changeBody(form.id);forms.append(b);}if(body.equipped){const leave=el('button','','Return to unchanged form · free');leave.type='button';leave.disabled=bodyState.mode!=='field';leave.onclick=()=>changeBody(null);forms.append(leave);}bodyPanel.append(forms,el('small','','One body history at a time. A first attunement is free; subsequent attunements spend one Ether. Histories remain available to this traveller in later tellings.'));}else bodyPanel.append(el('p','traveller-legacy-hint','Protect machinery or supplies to earn the kiln-grown arm. Guide or spare another life to earn the reed-tuned ear. Discover a rule or scout a new approach to earn the ash-bound shadow. Every traveller can earn each history.'));
 function changeBody(form){if(!equipLegacy(bodyState,id,form)){status.textContent='Attune between encounters. A later attunement needs one Ether.';return;}if(profile){profile.value.world.heroLegacies=structuredClone(bodyState.heroLegacies);if(bodyState===state)profile.value.world.items=structuredClone(bodyState.items);syncHeroLegacies(profile.value.world);writeJourneyProfile(localStorage,profile.value);profile.savedAt=Date.now();}if(bodyState===state)onLegacyChange(state,id);render();status.textContent=form?'Attuned '+HERO_TRANSFORMATIONS.find(t=>t.id===form).name+'. Its tradeoff travels with you.':'The unchanged form is restored. Your earned histories remain.';}
 details.append(fold('body','Growth & body histories'+(body.equipped?' · '+body.traitName:''),bodyPanel));
 const connections=el('div','traveller-connections'),seam=el('p','traveller-seam',bio[2]);connections.append(seam,el('p','traveller-bond','FIRST CONNECTION · '+bio[3]));
 const route=el('div','traveller-route');for(const [label,text]of [['BEGINNING','Repair · encounter or diversion · a lasting civic decision'],['THE ROADS MEET','Keep '+CREW[id].name+' in front · '+(id===0?'bring the reed to Rook':'meet Sable')+' · gather the crew'],['SHARED WORLD','24 story chapters · regional commissions in the same save']]){const step=el('div');step.append(el('small','',label),el('span','',text));route.append(step);}connections.append(route);details.append(fold('connections','How this life joins the others',connections));
 const setup=el('div','traveller-weave'),label=el('label','','Starting discipline'),select=el('select');select.setAttribute('aria-label','Starting discipline');for(const a of APPROACHES){const opt=el('option','',a.name);opt.value=a.id;opt.selected=a.id===weave.approach;select.append(opt);}label.append(select);const role=el('p','traveller-role',APPROACHES.find(a=>a.id===weave.approach).text);select.onchange=()=>{weave.approach=select.value;role.textContent=APPROACHES.find(a=>a.id===weave.approach).text;};const thread=el('label','','Thread to carry'),threads=el('select');threads.setAttribute('aria-label','Thread to carry');for(const t of THREADS){const opt=el('option','',t.name+' · '+t.label);opt.value=t.id;opt.selected=t.id===weave.thread;threads.append(opt);}threads.onchange=()=>weave.thread=threads.value;thread.append(threads);const reroll=el('button','traveller-reroll','↻ Reroll starting weave');reroll.onclick=()=>{weave=rerollJourney(id,weave);drafts.set(id,weave);render();details.querySelector('.traveller-reroll')?.focus({preventScroll:true});};setup.append(label,role,thread,reroll,el('small','','Rerolls change starting supplies and item discipline. They do not lock classes or decide your historical choices.'));details.append(fold('setup','Starting approach · '+APPROACHES.find(a=>a.id===weave.approach).name,setup));
 const actions=el('div','traveller-actions');if(summary){const resume=el('button','primary','Continue '+CREW[id].name+' · '+summary.label);resume.onclick=()=>action(()=>onResume?.(id));actions.append(resume);}const begin=el('button',summary?'':'primary',(summary?'New telling as ':'Begin as ')+CREW[id].name);begin.onclick=()=>action(()=>{const heritage=normalizeHeroLegacies(legacy.heroLegacies||state.heroLegacies),savedHeritage=normalizeHeroLegacies(bodyState.heroLegacies);heritage.heroes[id]=savedHeritage.heroes[id];onStart(selected.id,{...legacy,heroLegacies:heritage,unlocked:[0,1,2,3,4,5,6]},weave);});actions.append(begin);if(summary?.ready&&canJoin&&!(state?.party||[]).includes(id)){const join=el('button','traveller-join','＋ '+CREW[id].name+' joins your active crew');join.onclick=()=>action(()=>onJoin?.(id));actions.append(join);}else if(summary&&!summary.ready)actions.append(el('small','','Finish their beginning or current encounter to make them ready to join another crew.'));
